/**
 * 解説記事の本文。
 *
 * 書き方の決まり
 *   - 難易度・問題数・想定学習時間・到達目安は本文に直接書かない。
 *     bookTable ブロックで BOOKS から引く。記事とデータがずれないようにするため。
 *   - 本文中の [[id]] または [[id|表示名]] は、その書籍の個別ページへのリンクになる。
 *     id が BOOKS に無ければビルドが止まる（リンク切れを出さない）。
 *   - **強調** は <b> になる。
 *   - 断定できるのは、収録データと算術（時間の割り算など）から言えることまで。
 *     出典のない合格実績・体験談は書かない。
 *   - `category` は必須。build/content/article-categories.mjs の id から選ぶ。
 *     アイブロウ（Versus / Ranking など）はジャンルから出るので記事側に書かない。
 *
 * 使えるブロック
 *   { p }            段落
 *   { h3 }           小見出し
 *   { ul: [...] }    箇条書き
 *   { note, noteTitle } 囲み
 *   { bookTable: [id], columns? }  仕様の比較表
 *   { books: [id], dir? }          書影つきカード
 *   { versus: [id,id(,id)], dir?, verdict? }  一騎打ち。強み・注意点は pros / cons から出る
 *   { rankTable: [{id, dir?, note}], columns?, caption?, whyLabel? }  人が付けた順位
 *   { awards: [{title, dir, id, reason}] }    部門別。科目をまたいでよい
 *   { dataRank: {dirs?|dir?, by:'h'|'diff'|'year', order, limit, stages?, excludeStages?, subs?, caption?} }
 *   { pubRank: {dirs?|dir?, limit?, stages?, excludeStages?, subs?, caption?} }
 *   { hist: {by:'diff'|'year', dirs?|dir?, stages?, excludeStages?, subs?, caption?} }
 *   { stageTally: {dir?, excludeStages?, subs?, caption?} }
 *   { routeHoursTotal } / { routeHoursBySubject }   ルート合計時間
 *
 * **順位を人が付けるブロック（rankTable / awards）を使うときは、
 * 何を基準に並べたのかを必ず地の文に書く。**書かないと、読者は
 * データから出た順位と区別できない。
 */

