  desc: '化学の参考書の組み方。理論・無機・有機それぞれで必要な勉強が違うことを踏まえ、講義系（宇宙一・岡野・鎌田）、演習（重要問題集・新標準演習）、辞書（新研究）の使い分けを整理します。',
