  desc: '共通テスト英語リーディングで時間が足りなくなる原因を、語彙・構文・設問処理の3つに切り分けて対策を整理。速読の練習を始める前に確認すべきことと、対策本・実戦問題集の選び方をまとめます。',
  lead: '共通テストの英語リーディングは、**発音・アクセントや文法の単独問題が姿を消し、すべて読解の形式**になりました。その結果、最も多い失点理由が「解けなかった」ではなく「最後まで到達しなかった」に変わっています。時間が足りないと感じたとき、多くの人はすぐ速読の練習を始めますが、**速度は原因ではなく結果**です。この記事では、原因を 3 つに切り分けたうえで、それぞれに効く対策を整理します。',
