          '**通読して理解を作る** → [[yamakawa-omoshiroi|山川喜輝の生物が面白いほどわかる本]]や[[omori-nyushi-kogi|大森徹の入試生物の講義]]。独学で最初に通す 1 冊として使えます。',
          '**上位大で生物を得点源にする** → [[tabe-77ko|生物合格77講]]または[[omori-saikyo-kogi-126|大森徹の最強講義126講]]。情報量が多く、辞書としても長く使えます。',
