  lead: '社会の科目選択は、**受験勉強の総時間を最も大きく左右する判断**です。同じ志望校でも、選ぶ科目によって必要な時間が変わります。それにもかかわらず、「なんとなく好きだから」「学校で取ったから」で決まってしまうことが多い。この記事では、4 つの選択肢の作りの違いを整理し、判断の順番を示します。',
