  lead: '過去問は「実力がついてから解くもの」と言われます。もっともらしく聞こえますが、この考え方で進めると**過去問に入る前に受験が来ます**。実力がつくのを待っていると、着手はどこまでも後ろにずれるからです。この記事では、必要な年数と 1 年分あたりの時間から逆算して、いつ始めるべきかを具体的に出します。',
